parameters.jsCode:
const v = $json;

return [{
  json: {
    pickup: v['Pickup Location'],
    dropoff: v['Dropoff Location'],
    pickupDate: v['Pickup Date'],
    dropoffDate: v['Dropoff Date'],
    driverAge: Number(v['Driver Age'] || 30),
    carIndex: Math.max(0, Number(v['Car Index'] || 0))
  }
}];

const form = $items('Normalize Car Input', 0, 0)[0].json;

const pickupRaw = $items('Search Pickup Location', 0, 0)[0].json.response?.[0]?.text || '{}';
const dropoffRaw = $items('Search Dropoff Location', 0, 0)[0].json.response?.[0]?.text || '{}';

let pickupParsed = {};
let dropoffParsed = {};

try {
  pickupParsed = JSON.parse(pickupRaw);
} catch {}

try {
  dropoffParsed = JSON.parse(dropoffRaw);
} catch {}

const pickupList = pickupParsed.result || pickupParsed.data || [];
const dropoffList = dropoffParsed.result || dropoffParsed.data || [];

const pickupLocation = Array.isArray(pickupList) ? pickupList[0] : null;
const dropoffLocation = Array.isArray(dropoffList) ? dropoffList[0] : null;

if (!pickupLocation) {
  throw new Error('Pickup location not found');
}

if (!dropoffLocation) {
  throw new Error('Dropoff location not found');
}

const pickupCode = pickupLocation.code || pickupLocation.iata || pickupLocation.id;
const dropoffCode = dropoffLocation.code || dropoffLocation.iata || dropoffLocation.id;

return [{
  json: {
    pickupCode,
    dropoffCode,
    pickupLocation,
    dropoffLocation,
    pickupDate: form.pickupDate,
    dropoffDate: form.dropoffDate,
    driverAge: form.driverAge,
    carIndex: form.carIndex
  }
}];

const ctx = $items('Prepare Car Search', 0, 0)[0].json;

const raw = $json.response?.[0]?.text || '{}';

let parsed = {};

try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid car_search response JSON');
}

const cars =
  parsed.result ||
  parsed.data ||
  parsed.cars ||
  [];

if (!Array.isArray(cars) || cars.length === 0) {
  throw new Error('No cars found');
}

const index = Math.min(
  Number(ctx.carIndex || 0),
  cars.length - 1
);

const selectedCar = cars[index];

const fareCode =
  selectedCar.fareCode ||
  selectedCar.rateCode ||
  selectedCar.id ||
  '';

if (!fareCode) {
  throw new Error('fareCode missing');
}

return [
  {
    json: {
      ...ctx,
      correlationId:
        parsed.correlationId || '',

      selectedCar,

      fareCode,

      currency:
        parsed.currency || 'USD',

      totalResults:
        parsed.count || cars.length
    }
  }
];

