parameters.jsCode:
const paymentRaw = $json.response?.[0]?.text || '{}';
const revalidateRaw = $items('Car Revalidate', 0, 0)[0].json.response?.[0]?.text || '{}';
const carCtx = $items('Prepare Car Selection', 0, 0)[0].json;

let payment = {};
let revalidated = {};

try {
  payment = JSON.parse(paymentRaw);
} catch {}

try {
  revalidated = JSON.parse(revalidateRaw);
} catch {}

return [{
  json: {
    success: true,
    pickup: carCtx.pickupCode,
    dropoff: carCtx.dropoffCode,
    pickupDate: carCtx.pickupDate,
    dropoffDate: carCtx.dropoffDate,
    car: carCtx.selectedCar,
    revalidated,
    payment
  }
}];
